using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Security.Principal;
using System.Text;
namespace Aurora {
public static class ExtendedChecks {
    static readonly List<string> Report=new List<string>();static int failures;
    static string Root{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"extended-lab");}}
    public static bool Allowed(){return Environment.UserName.Equals("WDAGUtilityAccount",StringComparison.OrdinalIgnoreCase)&&File.Exists(@"C:\OuOLab\isolated.marker")&&AppDomain.CurrentDomain.BaseDirectory.StartsWith(@"C:\OuOLab\",StringComparison.OrdinalIgnoreCase)&&new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}
    static void Save(){string[] lines=Report.ToArray();File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"extended-results.txt"),lines,new UTF8Encoding(true));if(Directory.Exists(@"C:\OuOResults"))File.WriteAllLines(@"C:\OuOResults\extended-results.txt",lines,new UTF8Encoding(true));}
    static void Step(string text){Report.Add("STEP • "+text);Save();}
    static void Test(string name,Func<string> action){if(File.Exists(@"C:\OuOInput\skip-long-tests.flag")&&(name.StartsWith("DISM")||name.StartsWith("SFC")||name.StartsWith("Real Office"))||File.Exists(@"C:\OuOInput\skip-office-test.flag")&&name.StartsWith("Real Office")){Report.Add("UNVERIFIED • "+name+" • Not repeated in this fast iteration; earlier full-run evidence is retained separately.");Save();return;}Report.Add("RUNNING • "+name);Save();var watch=Stopwatch.StartNew();try{Report.Add("PASS • "+name+" • "+action()+" • "+watch.Elapsed.TotalSeconds.ToString("0.0")+" s");}catch(PlatformNotSupportedException ex){Report.Add("UNVERIFIED • "+name+" • "+ex.Message);}catch(Exception ex){failures++;Report.Add("FAIL • "+name+" • "+ex);}Save();}
    static string Servicing(string arguments,int timeout){var r=Runner.Run("dism.exe",arguments,timeout);if(r.Code==50||r.Code==87||r.Code==unchecked((int)0x800f080c)||r.Code==unchecked((int)0x800f081f)||r.Code==unchecked((int)0x800f0906))throw new PlatformNotSupportedException("Sandbox servicing returned "+r.Code+" • "+r.Output);if(r.Code!=0&&r.Code!=3010)throw new IOException("DISM "+r.Code+" • "+r.Output);return r.Output;}
    public static int Run(){
        if(!Allowed())return 80;Directory.CreateDirectory(Root);Report.Add("Extended disposable validation • "+DateTime.Now.ToString("s")+" • "+Environment.OSVersion.Version);Report.Add("Only the disposable guest is modified. Unavailable facilities remain UNVERIFIED, never counted as a pass.");
        Test("Real Cloud Files hydration using a disposable local provider",()=>{try{return CloudProviderCheck.Run(Root);}catch(DllNotFoundException ex){throw new PlatformNotSupportedException(ex.Message);}catch(System.Runtime.InteropServices.COMException ex){int code=ex.ErrorCode&65535;if(code==50||code==379||code==1060||code==1058)throw new PlatformNotSupportedException("Cloud Files unavailable in this guest: "+ex.Message);throw;}});
        Test("Actual System Restore point creation",()=>{var result=Runner.PS("$ErrorActionPreference='Stop';$before=@(Get-ComputerRestorePoint|ForEach-Object SequenceNumber);Checkpoint-Computer -Description 'OuO disposable validation' -RestorePointType MODIFY_SETTINGS;$new=@(Get-ComputerRestorePoint|Where-Object {$before -notcontains $_.SequenceNumber -and $_.Description -eq 'OuO disposable validation'});if($new.Count -eq 0){throw 'No new restore point was created'};'CREATED '+$new[0].SequenceNumber",120000);if(result.Code!=0||!result.Output.Contains("CREATED"))throw new PlatformNotSupportedException("Guest does not provide an operational System Restore provider: "+result.Output);return result.Output;});
        Test("Install and remove an inbox signed driver on a guest-only virtual device",()=>VirtualDriverCheck.Run());
        Test("Real MSI installation, inventory and production uninstall",()=>InstallerFixtureCheck.Run(Root));
        Test("Live local-account password reset and credential validation",()=>LocalAccountCheck.Run());
        Test("Real Registry backup/restore and permanent temporary-file cleanup",()=>CleanupFixtureCheck.Run(Root));
        Test("Direct MFT scan with sixteen thousand generated files",()=>LargeMftCheck.Run(Root));
        Test("DISM online checks, repair when needed and post-repair verification",()=>{Step("DISM /CheckHealth");Servicing("/Online /Cleanup-Image /CheckHealth /English /NoRestart",120000);Step("DISM /ScanHealth");string scan=Servicing("/Online /Cleanup-Image /ScanHealth /English /NoRestart",600000);bool repaired=false;if(scan.IndexOf("The component store is repairable",StringComparison.OrdinalIgnoreCase)>=0){Step("Guest component store is repairable; DISM /RestoreHealth");Servicing("/Online /Cleanup-Image /RestoreHealth /English /NoRestart",900000);Step("Verify again after DISM repair");scan=Servicing("/Online /Cleanup-Image /ScanHealth /English /NoRestart",600000);repaired=true;}if(scan.IndexOf("No component store corruption detected",StringComparison.OrdinalIgnoreCase)<0)throw new PlatformNotSupportedException("Guest component store not confirmed healthy after attempted repair: "+scan);return repaired?"Real guest component-store repair completed; a second scan confirmed no corruption.":"Checks completed; no corruption detected. Repair on a damaged OS was not exercised.";});
        Test("SFC verification on the disposable Windows",()=>{var r=Runner.Run("sfc.exe","/verifyonly",600000);File.WriteAllText(Path.Combine(Root,"sfc.txt"),r.Output,Encoding.UTF8);if(r.Code!=0)throw new PlatformNotSupportedException("SFC verification unavailable/unsuccessful in this guest: "+r.Code+" • "+r.Output);if(r.Output.IndexOf("did not find any integrity violations",StringComparison.OrdinalIgnoreCase)<0&&r.Output.IndexOf("não encontrou nenhuma violação",StringComparison.OrdinalIgnoreCase)<0)throw new PlatformNotSupportedException("SFC did not report a complete, clean verification: "+r.Output);return "Real protected-file verification completed; repair on a damaged Windows still requires a dedicated image.";});
        Test("Real Office download, installation and uninstall in the disposable guest",()=>{var r=Runner.Run(System.Reflection.Assembly.GetExecutingAssembly().Location,"--office-lab-worker",1800000);string path=Path.Combine(Root,"office-result.txt"),result=File.Exists(path)?File.ReadAllText(path):r.Output;if(r.Code==3||r.Code==-1)throw new PlatformNotSupportedException("Office trial not completed: "+result);if(r.Code!=0)throw new IOException("Office fixture failed: "+r.Code+" • "+result);return result;});
        Report.Add("RESULT • "+failures+" failure(s); "+Report.Count(x=>x.StartsWith("PASS •"))+" passed; "+Report.Count(x=>x.StartsWith("UNVERIFIED •"))+" unverified. No host operating system, Office installation or physical device modified.");Save();return failures==0?0:1;
    }
    public static int OfficeWorker(){
        if(!Allowed())return 80;Directory.CreateDirectory(Root);string result;int code=0;
        try{var previous=OfficeReplacement.Inventory();if(previous.Count!=0){bool owned=previous.Count==1&&previous[0].Contains("O365ProPlusRetail")&&Directory.GetFiles(@"C:\OuOLab","office-progress.txt",SearchOption.AllDirectories).Any(x=>File.ReadAllText(x).Contains("Instalando os aplicativos selecionados")||File.ReadAllText(x).Contains("Installing selected apps"));if(!owned)throw new PlatformNotSupportedException("Guest already contains Office without an owned-trial record; refusing to remove an unrelated installation.");string oldTool=Directory.GetFiles(DailyMaintenance.Root,"setup.exe",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTimeUtc).First();OfficeConfiguration.VerifyTool(oldTool);OfficeReplacement.RemoveClickToRun(oldTool,Root,s=>File.AppendAllText(Path.Combine(Root,"office-progress.txt"),s+Environment.NewLine));}var job=new OfficeAutoJob{Product="O365ProPlusRetail",Architecture="64",Language="en-us",Apps=new[]{"Word"},AcceptTerms=true};
            string install=OfficeAutomatic.Install(job,s=>{File.AppendAllText(Path.Combine(Root,"office-progress.txt"),DateTime.Now.ToString("s")+" "+s+Environment.NewLine);if(Directory.Exists(@"C:\OuOResults"))File.WriteAllText(@"C:\OuOResults\office-progress.txt",s,Encoding.UTF8);});
            string word=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"Microsoft Office\root\Office16\WINWORD.EXE");if(!File.Exists(word)||!OfficeReplacement.Inventory().Any(x=>x.StartsWith("Office Click-to-Run")))throw new InvalidDataException("Installer finished without a detected Word installation.");string version=FileVersionInfo.GetVersionInfo(word).FileVersion;
            string odt=Directory.GetFiles(DailyMaintenance.Root,"setup.exe",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTimeUtc).First();OfficeReplacement.RemoveClickToRun(odt,Root,s=>File.AppendAllText(Path.Combine(Root,"office-progress.txt"),s+Environment.NewLine));if(File.Exists(word))throw new InvalidDataException("Word binary remains after ODT uninstall.");result="Word "+version+" installed and removed with official ODT; no activation attempted. "+install;
        }catch(WebException ex){code=3;result="Network/download unavailable: "+ex.Message;}catch(PlatformNotSupportedException ex){code=3;result=ex.Message;}catch(Exception ex){code=1;result=ex.ToString();}
        File.WriteAllText(Path.Combine(Root,"office-result.txt"),result,new UTF8Encoding(true));return code;
    }
}
}
